function countSpellings(words: string[], target: string): number {
  const MOD = 1_000_000_007, L = words[0].length, m = target.length;
  const go = (i: number, col: number): number => {
    if (i === m) return 1;
    let total = 0;
    for (let c = col; c < L; c++) {
      let hits = 0;
      for (const w of words) if (w[c] === target[i]) hits++;
      if (hits) total = (total + hits * go(i + 1, c + 1)) % MOD;
    }
    return total;
  };
  return go(0, 0);
}

