function countSpellings(words: string[], target: string): number {
  const MOD = 1_000_000_007, L = words[0].length, m = target.length;
  const count: number[][] = Array.from({ length: L }, () => new Array(26).fill(0));
  for (const w of words) for (let c = 0; c < L; c++) count[c][w.charCodeAt(c) - 97]++;
  const ways = new Array(m + 1).fill(0);
  ways[0] = 1;
  for (let c = 0; c < L; c++) {
    // downward so this column is used for at most one letter
    for (let i = Math.min(m, c + 1); i >= 1; i--) {
      const k = count[c][target.charCodeAt(i - 1) - 97];
      if (k) ways[i] = (ways[i] + ways[i - 1] * k) % MOD;
    }
  }
  return ways[m];
}

