class Solution:
    def countSpellings(self, words: List[str], target: str) -> int:
        MOD, L, m = 10**9 + 7, len(words[0]), len(target)
        count = [Counter() for _ in range(L)]
        for w in words:
            for c, ch in enumerate(w):
                count[c][ch] += 1
        ways = [1] + [0] * m
        for c in range(L):
            col = count[c]
            # downward so this column is used for at most one letter
            for i in range(min(m, c + 1), 0, -1):
                k = col[target[i - 1]]
                if k:
                    ways[i] = (ways[i] + ways[i - 1] * k) % MOD
        return ways[m]

